from lib import *
R = J('u40'); S = SS('u40')
rows = R['sizes']; tg1, tg8, td8 = R['times']
steps = [
    step(f"单态化:describe<T: Display + Copy> 在 8 种类型(u8、i16、i32、i64、f32、f64、char、&str)上使用,汇编里就有 {R['n_syms']} 个独立的 describe 函数符号 —— 每个具体类型一份,各自针对该类型编译与优化。", t=tl(S(1)), done=lidx(S(1), '__R'), kv=KV([['8 种类型', f"{R['n_syms']} 个函数"]], ['8 种类型'])),
    step(f"代码体积随类型数增长:泛型版的 .o 文件(-O)从 1 种类型的 {rows[0][1]:,} 字节,到 2、4、8 种类型的 {rows[1][1]:,}、{rows[2][1]:,}、{rows[3][1]:,} 字节;&dyn 版虽然只有一份函数体,但每个类型还要生成 vtable 与转换代码,同样的 1、2、4、8 种类型是 {rows[0][2]:,}、{rows[1][2]:,}、{rows[2][2]:,}、{rows[3][2]:,} 字节 —— 增长得更慢(起点更高,因为要多一层间接调用)。这个函数体很小,函数越大,单态化膨胀得越明显。", t=tl(S(2)), b=bars([[f'{n} 种类型 泛型', a, f'{a:,} B'] for n, a, _ in rows] + [[f'{n} 种类型 &dyn', b, f'{b:,} B'] for n, _, b in rows], max(max(a, b) for _, a, b in rows), done=[0, 1, 2, 3], mark=[4, 5, 6, 7]), kv=KV([['泛型 1 → 8 种类型', f'{rows[0][1]:,} → {rows[3][1]:,} B'], ['&dyn 1 → 8 种类型', f'{rows[0][2]:,} → {rows[3][2]:,} B']], ['泛型 1 → 8 种类型'])),
    step(f"编译时间也随之增长:rustc -O 编译这个很小的 crate(3 次取中位数),泛型版 1 种类型约 {tg1*1000:.0f} ms,8 种类型约 {tg8*1000:.0f} ms;&dyn 版 8 种类型约 {td8*1000:.0f} ms。代价是真实的,但在小函数上不大;大型泛型代码(比如迭代器链、async 状态机)会更明显。", t=tl(S(3)), b=bars([['泛型 1 种类型', tg1 * 1000, f'{tg1*1000:.0f} ms'], ['泛型 8 种类型', tg8 * 1000, f'{tg8*1000:.0f} ms'], ['&dyn 8 种类型', td8 * 1000, f'{td8*1000:.0f} ms']], max(tg8, td8) * 1000, mark=[1], done=[0, 2]), kv=KV([['泛型 1 → 8 种类型', f'{tg1*1000:.0f} → {tg8*1000:.0f} ms']], ['泛型 1 → 8 种类型'])),
]
A = mkart('u40', 40, 'Rust,泛型,单态化,代码体积,编译时间,真实验证,动画演示',
    f'用真实编译验证单态化:一个泛型函数用在 8 种类型上生成 {R["n_syms"]} 个函数符号;.o 体积随类型数从 {rows[0][1]:,} 增长到 {rows[3][1]:,} 字节(&dyn 版从 {rows[0][2]:,} 到 {rows[3][2]:,});编译时间从 {tg1*1000:.0f} ms 增到 {tg8*1000:.0f} ms。',
    '泛型在 Rust 里是零运行时开销的,代价记在编译期:每个具体类型一份代码。这篇不空谈「代码膨胀」,而是真的数符号、量 .o 文件大小、量编译时间,并和 &dyn 版本对比 —— 结果比「泛型一定更大」要微妙。',
    [(f'{R["n_syms"]} 个', '同一个泛型函数在 8 种类型上生成的函数个数'), (f'{rows[0][1]:,} → {rows[3][1]:,} B', '泛型版 .o 大小从 1 种到 8 种类型'), (f'{tg1*1000:.0f} → {tg8*1000:.0f} ms', '编译时间从 1 种到 8 种类型(小例子)')],
    [('每个类型一份', None), ('代码体积', '<p>.o 文件大小是粗略指标(包含符号表、元数据等),不等于最终可执行文件里的代码段大小。</p>'), ('编译时间', '<p>更多关于编译时间与二进制体积的分析见<a href="rust-compile-time-analysis.html">编译时间分析</a>与<a href="rust-binary-size-analysis.html">二进制体积分析</a>;分发方式的运行时对比见<a href="rust-static-vs-dynamic-dispatch.html">静态分发与动态分发性能对比</a>。</p>')],
    steps, [ENV_U + '。.o 体积来自 --emit=obj -O -C codegen-units=1;时间为 3 次中位数,rustc 单次编译 40–90 ms 量级,噪声不小', '没有验证:大型泛型函数上的体积膨胀倍数、-C opt-level=s/z 的影响、-Zshare-generics、LTO 对重复实例的合并、泛型代码对指令缓存的影响'], '单态化')
